    int h = blockIdx.y;
    int q_pos = blockIdx.z;

    int num_heads = gridDim.y;
    int kv_h = h / (num_heads / num_kv_heads);
    int base_q = (b * num_heads + h) * q_len * head_dim + q_pos * head_dim;
    int base_kv = (b * num_kv_heads + kv_h) * kv_len * head_dim;
    int full_q_pos = kv_len - q_len + q_pos;

    int tid = threadIdx.x;
    int bdim = blockDim.x;

    // Each thread handles head_dim/bdim elements (rounded up)
    int elems_per_thread = (head_dim + bdim - 1) / bdim;

    // Load Q elements into registers
    float q_vals[MAX_ELEMS]; // MAX_ELEMS = 2 or 4
    for (int i = 0; i < elems_per_thread; i++) {
        int d = tid + i * bdim;
        if (d < head_dim) {
            q_vals[i] = static_cast<float>(__ldg(&Q[base_q + d]));
        }
    }

    // Online softmax + weighted V accumulation
    float max_score = -FLT_MAX;
    float sum_exp = 0.0f;
    float acc[MAX_ELEMS] = {0.0f};

    for (int j = 0; j < kv_len; j++) {
        // Causal mask
        if (causal && j > full_q_pos) continue;

        // Compute dot product
        float dot = 0.0f;
        int base_k = base_kv + j * head_dim;
        for (int i = 0; i < elems_per_thread; i++) {
            int d = tid + i * bdim;
            if (d < head_dim) {
